"""Independent acceptance configurations; protected R01-R09 records stay unchanged."""
from common import *
import copy,yaml

def build():
 require('R09');out=edition('R10');out.mkdir(parents=True,exist_ok=True);build_spray();cfg=read(out/'spray/mission.json');r8=read(edition('R08')/'mission.json')
 build_mowing()
 catalog=dict(schema='R10-INDEPENDENT-ACCEPTANCE/1',formal_S17_S18='PARTIAL',normal_required=['spray_full_A1','inspection_full_connector','mowing_full_B1'],fault_required=['spray_tool_jam','inspection_follow_stop_resume','inspection_detour','inspection_persistent_block','mowing_persistent_block','mowing_startup_perception_loss'],original_denominators=dict(A1_points=len(cfg['clusters'][0]['points']),B1_segments=len(read(edition('R09')/'mission.json')['clusters'][0]['segments']),connector_m=r8['original_route_length_m']),scope='Independent normal and bounded-fault acceptance, no sixty-run matrix and no extrapolation to untested A2/A3/B2/B3');catalog['version']=canonical(catalog);dump(out/'catalog.json',catalog);return out


def build_mowing():
 require('R09');out=edition('R10');out.mkdir(parents=True,exist_ok=True)
 mowing=out/'mowing';mowing.mkdir(exist_ok=True);mc=copy.deepcopy(read(edition('R09')/'mission.json'));mc.pop('version');mc['navigation_execution']=dict(mode='original_primitive_boundaries',retry_limit_per_original_segment=6,turn_nominal_speed_mps=.35,turn_curvature_lookahead_m=.8,preserve_original_waypoints=True,intermediate_xy_tolerance_m=.10,intermediate_yaw_tolerance_rad=.12,stop_at='each original kinematic primitive, including curvature and gear boundaries',original_segment_denominator_unchanged=True,endpoint_recovery=dict(planner='SmacHybrid with continuous OMPL ReedsShepp fallback and full costmap admission',controller='MPPI_Ackermann',max_attempts=2,max_sim_seconds=90.,max_length_m=12.,gear_change_requires_measured_stop=True,path_costs_remain_active_near_original_goal=True,max_observation_resumes=6,pause_policy='cancel, measured stop, fresh BT clearance, bounded cursor, full footprint and live costmap revalidation; original 90s budget'));mc['startup_cancellation']=dict(priority='fresh EXECUTE required throughout START_WORK; cancel before confirming readiness',stop_confirmation_s=2.,maximum_start_s=8.,resume='physical stop then fresh BT directive; same idempotency key and original segment retry budget');mc['ledger_transport']=dict(heartbeat_clock='STEADY_TIME',heartbeat_wall_s=.05,tool_server_stale_wall_s=.25,simulation_stamps_and_feedback_guards='unchanged');mc['version']=canonical(mc);dump(mowing/'mission.json',mc)
 mt=read(edition('R09')/'tool.json');mt['plan_revision']=mc['version'];mt.pop('tool_revision');mt['tool_revision']=canonical(mt);dump(mowing/'tool.json',mt)
 for file in ['nav2.yaml','manager.json','terrain.json']:(mowing/file).write_bytes((edition('R09')/file).read_bytes())
 mn=yaml.safe_load((mowing/'nav2.yaml').read_text());controller=mn['controller_server']['ros__parameters'];controller['controller_plugins']=['RPP','TurnRPP','RecoveryMPPI'];turn=copy.deepcopy(controller['RPP']);controller['TurnRPP']=turn
 recovery=copy.deepcopy(controller['MPPI']);recovery.update(plugin='nav2_mppi_controller::MPPIController',motion_model='Ackermann',time_steps=80,batch_size=750,vx_max=.25,vx_min=-.25,vx_std=.10,wz_std=.025,wz_max=.085,prune_distance=4.,max_robot_pose_search_dist=.35,enforce_path_inversion=True,inversion_xy_tolerance=.08,inversion_yaw_tolerance=.10)
 recovery.pop('implementation',None);recovery['AckermannConstraints']['min_turning_r']=1/mc['vehicle']['steering']['max_curvature'];recovery['critics'].remove('PreferForwardCritic');recovery['PathAngleCritic']['mode']=2;recovery['ConstraintCritic']['cost_weight']=25.;recovery['PathAlignCritic'].update(cost_weight=80.,threshold_to_consider=0.);recovery['PathFollowCritic'].update(cost_weight=40.,threshold_to_consider=0.);recovery['PathAngleCritic'].update(cost_weight=8.,threshold_to_consider=0.);recovery['GoalAngleCritic'].update(cost_weight=8.,threshold_to_consider=1.);recovery['GoalCritic'].update(cost_weight=5.,threshold_to_consider=1.)
 controller['RecoveryMPPI']=recovery;mn['planner_server']['ros__parameters']['GridBased'].update(smooth_path=False,tolerance=.05)
 (mowing/'nav2.yaml').write_text(yaml.safe_dump(mn,sort_keys=False))
 return mowing


def build_spray():
 require('R09');out=edition('R10');out.mkdir(parents=True,exist_ok=True);s=out/'spray';s.mkdir(exist_ok=True);cfg=copy.deepcopy(read(edition('R07')/'mission.json'));r8=read(edition('R08')/'mission.json')
 for key in ['localization_surface_window','local_motion_integrity','global_reference_checks','ground_statistic']:cfg[key]=r8[key]
 cfg['global_correction_filter']=dict(tau_s=.8,scope='map to odom correction only; raw jump, GNSS innovation, freshness and plan hold unchanged; all docking gates unchanged')
 cfg.update(navigation_recovery=dict(near_radius_m=.25,minimum_improvement_m=.005,stall_s=8.,minimum_translation_command_s=2.,maximum_sample_gap_s=.15),speed_cap_mps=.30,yaw_cap_rps=.35,docking_admission=dict(navigation_goal_m=.025,median_distance_m=.035,latest_distance_m=.045,scatter_p95_m=.015,span_s=1.8,max_observation_wait_s=8.),acceleration_profile='RPP .28m/s desired, 1.4m curvature regulation radius, .25rad/s rotation, .40rad/s2 angular acceleration; physical drivetrain limits retained',schema='R10-SPRAY-ACCEPTANCE/1',scope='Original A1 complete point list; updated R08 localization/terrain engine independently retested; prior R07 receipts retained');cfg.pop('version',None);cfg['version']=canonical(cfg);dump(s/'mission.json',cfg)
 tool=read(edition('R07')/'tool.json');tool['plan_revision']=cfg['version'];tool['feedback_period_s']=.02;tool.pop('tool_revision');tool['tool_revision']=canonical(tool);dump(s/'tool.json',tool)
 nav=yaml.safe_load((edition('R07')/'nav2.yaml').read_text());nav['controller_server']['ros__parameters']['DWB'].update(max_vel_x=.25,max_speed_xy=.25,max_vel_theta=.30,acc_lim_x=.30,acc_lim_theta=.40,decel_lim_x=-.45,decel_lim_theta=-.5);nav['controller_server']['ros__parameters']['RPP'].update(desired_linear_vel=.28,rotate_to_heading_angular_vel=.25,max_angular_accel=.40,regulated_linear_scaling_min_radius=1.4,regulated_linear_scaling_min_speed=.01,min_approach_linear_velocity=.01);nav['controller_server']['ros__parameters']['goal']['xy_goal_tolerance']=.025;nav['global_costmap']['global_costmap']['ros__parameters']['plugins']=['static','live_obstacles','inflation'];nav['global_costmap']['global_costmap']['ros__parameters']['live_obstacles']=dict(plugin='r08::ObservedPriorLayer',topic='/r07/risk_local',max_age=.6);(s/'nav2.yaml').write_text(yaml.safe_dump(nav,sort_keys=False));terrain=read(edition('R07')/'terrain.json');terrain.update(protective_half_width_m=max(abs(y) for x,y in cfg['vehicle']['footprint'])+.1,protective_front_m=1.4);dump(s/'terrain.json',terrain);manager=read(edition('R08')/'manager.json');manager['correction_filter_tau_s']=cfg['global_correction_filter']['tau_s'];dump(s/'manager.json',manager)
 from global_filter_r10 import build as build_global
 build_global()
 return s
